use crate::grid::P3;
use crate::sign::Sign;

use super::{decide, exact_f64, larger, largest_magnitude, rounded_f64, within};

/// The filter's error constant: E · (1 + 2u)^2 with E = 11u + 7u^2 + 2u^3, the result's unit error
/// (header), rounded up to an `f64`: 6192449487634436 · 2^-102.
const ERROR: f64 = f64::from_bits(0x3cd6_0000_0000_0004);

/// `lpi_weight`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    reason = "each name is a step of the description, named by the language's rule"
)]
pub fn filter(nx: i128, ny: i128, nz: i128, p: P3, q: P3) -> Option<Sign> {
    let qp_x = exact_f64(q.x) - exact_f64(p.x);
    let qp_y = exact_f64(q.y) - exact_f64(p.y);
    let qp_z = exact_f64(q.z) - exact_f64(p.z);
    let nx = rounded_f64(nx, 83)?;
    let w_1 = nx * qp_x;
    let ny = rounded_f64(ny, 83)?;
    let w_2 = ny * qp_y;
    let w_3 = w_1 + w_2;
    let nz = rounded_f64(nz, 83)?;
    let w_4 = nz * qp_z;
    let w = w_3 + w_4;
    let m_x = largest_magnitude([qp_x]);
    let m_y = largest_magnitude([qp_y]);
    let m_z = largest_magnitude([qp_z]);
    let m_n = largest_magnitude([nx, ny, nz]);
    let scale = m_n * larger(larger(m_z, m_y), m_x);
    decide(w, ERROR, scale)
}

/// `lpi_weight`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    reason = "each name is a step of the description, named by the language's rule"
)]
pub fn value(nx: i128, ny: i128, nz: i128, p: P3, q: P3) -> Option<i128> {
    let qp_x = q.x.get().checked_sub(p.x.get())?;
    let qp_y = q.y.get().checked_sub(p.y.get())?;
    let qp_z = q.z.get().checked_sub(p.z.get())?;
    let nx = within(nx, 83)?;
    let w_1 = nx.checked_mul(i128::from(qp_x))?;
    let ny = within(ny, 83)?;
    let w_2 = ny.checked_mul(i128::from(qp_y))?;
    let w_3 = w_1.checked_add(w_2)?;
    let nz = within(nz, 83)?;
    let w_4 = nz.checked_mul(i128::from(qp_z))?;
    let w = w_3.checked_add(w_4)?;
    Some(w)
}

/// `lpi_weight`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
pub fn exact(nx: i128, ny: i128, nz: i128, p: P3, q: P3) -> Option<Sign> {
    value(nx, ny, nz, p, q).map(Sign::of_i128)
}
